/** Seeds that need no search, for one object at one ruling. */
export function cubeRingDesigns(object: string, cells: number): readonly CubeRingDesign[] {
  return CUBE_RING_DESIGNS.filter(d => d.object === object && d.cells === cells);
}

/** The one for this object, ruling and seed, if it was worth keeping. */
export function cubeRingDesign(
  object: string,
  cells: number,
  seed: number,
): CubeRingDesign | null {
  return CUBE_RING_DESIGNS.find(d =>
    d.object === object && d.cells === cells && d.seed === seed) ?? null;
}
